import functools

def f(n):
    """Compute f(n) = max total distance of Hamiltonian cycle on {1,...,n}
    starting and ending at 1, with jumps of length <= 3."""
    if n == 1:
        return 0
    # vertices 0..n-1 (representing 1..n)
    # start at vertex 0 (lilypad 1)
    # DP over subsets
    INF = -1  # use -1 for impossible
    # dp[mask][v] = max distance of path from 0, visiting mask, ending at v
    # mask includes vertex 0
    full = (1 << n) - 1
    dp = [[INF] * n for _ in range(1 << n)]
    dp[1 << 0][0] = 0  # start at vertex 0, distance 0

    for mask in range(1 << n):
        if not (mask & 1):  # vertex 0 must be visited
            continue
        for v in range(n):
            if dp[mask][v] < 0:
                continue
            for u in range(n):
                if mask & (1 << u):
                    continue
                d = abs(u - v)
                if d > 3 or d == 0:
                    continue
                newmask = mask | (1 << u)
                dp[newmask][u] = max(dp[newmask][u], dp[mask][v] + d)

    # close the cycle: return to vertex 0
    best = INF
    for v in range(n):
        if dp[full][v] < 0:
            continue
        d = abs(v - 0)
        if d <= 3 and d > 0:
            best = max(best, dp[full][v] + d)
    return best

for n in range(2, 21):
    fn = f(n)
    print(f"n={n:2d}, f(n)={fn:3d}, f(n)/n={fn/n:.4f}")
